CustomField.formula:
/* 1. Calculate the Subtotal */
(Total_Parts_Cost__c + Total_Labor_Cost__c +  Misc_Fees__c  + Fixed_Cost__c)

+

/* 2. Calculate the Tax Amount */
(
  /* Always tax Parts and Misc/Fixed */
  (Total_Parts_Cost__c + Misc_Fees__c + Fixed_Cost__c) * Tax_Rate__c
  +
  /* Only tax Labor if the checkbox is TRUE */
  IF( Is_Labor_Taxable__c, (Total_Labor_Cost__c * Tax_Rate__c), 0 )
)
